<dialog id="image-picker" tabindex="-1" autofocus class="image-picker" aria-labelledby="image-picker-title"><h2 id="image-picker-title" class="sr-only"><?=e(t('Insert images'))?></h2><div class="image-picker-heading"><div role="tablist" aria-label="<?=e(t('Image source'))?>"><button type="button" role="tab" id="picker-tab-library" data-picker-tab="library" aria-controls="picker-library" aria-selected="true"><?=e(t('My images'))?></button><button type="button" role="tab" id="picker-tab-external" data-picker-tab="external" aria-controls="picker-external-panel" aria-selected="false"><?=e(t('External images'))?></button></div><button type="button" class="icon-button" id="close-image-picker" aria-label="<?=e(t('Close'))?>"><?=icon('close')?></button></div><div id="picker-library" role="tabpanel" aria-labelledby="picker-tab-library"><div class="image-picker-tools"><label class="sr-only" for="picker-search"><?=e(t('Search images'))?></label><div class="image-picker-search"><input id="picker-search" maxlength="200" placeholder="<?=e(t('Search images'))?>"><?=icon('search')?></div><button type="button" class="button" id="picker-upload-button"><?=icon('image')?><?=e(t('Upload'))?></button><input id="picker-upload-input" type="file" accept="image/png,image/jpeg,image/gif,image/webp" multiple hidden></div><div id="picker-grid" class="image-picker-grid"></div><div class="image-picker-pagination"><button type="button" class="text-button" id="picker-previous"><?=e(t('Previous'))?></button><span id="picker-page"></span><button type="button" class="text-button" id="picker-next"><?=e(t('Next'))?></button></div></div><div id="picker-external-panel" role="tabpanel" aria-labelledby="picker-tab-external" hidden><label for="picker-external"><?=e(t('Enter image URLs, one per line.'))?></label><textarea id="picker-external" rows="4" placeholder="https://…"></textarea></div><p id="picker-message" class="image-picker-message" role="status"></p><div class="image-picker-footer"><button type="button" class="text-button" id="picker-confirm"><?=e(t('Confirm'))?></button></div></dialog>
